// Extract Razorpay webhook payload
const body = $input.first().json.body;

console.log('Razorpay Webhook Received:', JSON.stringify(body, null, 2));

// Validate webhook event type
const event = body.event;
if (!event) {
  throw new Error('Invalid webhook: missing event field');
}

// Extract payment data based on event type
let razorpayOrderId, razorpayPaymentId, status;

if (event === 'payment.captured' || event === 'order.paid') {
  const payment = body.payload?.payment || body.payload?.order;

  if (!payment) {
    throw new Error('Invalid webhook: missing payment data');
  }

  razorpayOrderId = payment.order_id;
  razorpayPaymentId = payment.id;
  status = 'paid';

} else if (event === 'payment.failed') {
  const payment = body.payload?.payment;

  if (!payment) {
    throw new Error('Invalid webhook: missing payment data');
  }

  razorpayOrderId = payment.order_id;
  razorpayPaymentId = payment.id;
  status = 'failed';

} else {
  // Unsupported event type - acknowledge but don't process
  return {
    json: {
      success: true,
      message: 'Event acknowledged but not processed: ' + event,
      should_process: false
    }
  };
}

if (!razorpayOrderId) {
  throw new Error('Invalid webhook: missing order_id');
}

console.log('Processed Webhook Data:', {
  event,
  razorpayOrderId,
  razorpayPaymentId,
  status
});

return {
  json: {
    razorpay_order_id: razorpayOrderId,
    razorpay_payment_id: razorpayPaymentId,
    status: status,
    event: event,
    should_process: true,
    raw_payload: body
  }
};

// Extract payment and assessment details from database response
const dbResponse = $input.first().json;

console.log('DB Response:', JSON.stringify(dbResponse, null, 2));

// Handle response format (may be array or object)
let paymentData;
if (Array.isArray(dbResponse)) {
  paymentData = dbResponse[0];
} else {
  paymentData = dbResponse;
}

if (!paymentData) {
  throw new Error('No payment data returned from database');
}

const assessmentType = paymentData.assessment_type;
const assessmentLink = paymentData.assessment_link;
const parentName = paymentData.parent_name || 'Parent';
const phone = paymentData.phone;
const displayName = paymentData.assessment_type;

// Format display name
let formattedName = displayName;
if (assessmentType === 'iLMH') formattedName = 'iLMH Assessment';
else if (assessmentType === 'test_anxiety') formattedName = 'Test Anxiety Assessment';
else if (assessmentType === 'iTMPA') formattedName = 'iTMPA Assessment';
else if (assessmentType === 'iPMA') formattedName = 'iPMA Assessment';

// Create WhatsApp message
const message = `Payment received! 🎉\n\nThank you for your payment, ${parentName}!\n\nHere's your ${formattedName} link:\n${assessmentLink}\n\nPlease complete the assessment at your convenience. If you have any questions, feel free to ask!\n\n- Subbu Innovative Classes`;

return {
  json: {
    phone: phone,
    message: message,
    parent_name: parentName,
    assessment_type: assessmentType,
    assessment_link: assessmentLink
  }
};

// Log payment failure
const dbResponse = $input.first().json;

let paymentData;
if (Array.isArray(dbResponse)) {
  paymentData = dbResponse[0];
} else {
  paymentData = dbResponse;
}

const parentName = paymentData?.parent_name || 'Parent';
const phone = paymentData?.phone;

const message = `We noticed that the payment didn't go through. No worries!\n\nIf you'd like to try again, please let me know and I'll send you a fresh payment link.\n\nFeel free to reach out if you need any assistance!\n\n- Subbu Innovative Classes`;

return {
  json: {
    phone: phone,
    message: message,
    parent_name: parentName,
    should_notify: phone ? true : false
  }
};

// Log error for debugging
const error = $input.first().json;

console.error('Webhook Processing Error:', error);

// Notify admin about error
const errorMessage = error.message || 'Unknown error';

return {
  json: {
    error: true,
    message: errorMessage,
    timestamp: new Date().toISOString()
  }
};
